#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    long long x, y, b;
} Star;

static int cmp_brightness(const void *a, const void *b) {
    const Star *p = (const Star *)a;
    const Star *q = (const Star *)b;
    if (p->b < q->b) return -1;
    if (p->b > q->b) return 1;
    return 0;
}

int main(void) {
    int N;
    long long d;

    if (scanf("%d %lld", &N, &d) != 2) return 0;

    Star *stars = (Star *)malloc((size_t)N * sizeof(Star));
    for (int i = 0; i < N; ++i) {
        scanf("%lld %lld %lld", &stars[i].x, &stars[i].y, &stars[i].b);
    }

    qsort(stars, N, sizeof(Star), cmp_brightness);

    double best = 0.0;

    /* 
       For every valid brightness window [l..r], compute the convex hull
       of stars in that window and use rotating calipers to find the
       maximum triangle area among hull vertices.
       The answer is the largest possible area of a constellation where
       every pair has brightness difference <= d.
    */
    for (int l = 0; l < N; ++l) {
        int r = l;
        while (r + 1 < N && stars[r + 1].b - stars[l].b <= d) r++;

        int m = r - l + 1;
        if (m < 3) continue;

        /* Copy points of current window */
        typedef struct { long long x, y; } Point;
        Point *pts = (Point *)malloc((size_t)m * sizeof(Point));
        for (int i = 0; i < m; ++i) {
            pts[i].x = stars[l + i].x;
            pts[i].y = stars[l + i].y;
        }

        /* Sort points by x, then y */
        int cmp_point(const void *a, const void *b) {
            const Point *p = (const Point *)a;
            const Point *q = (const Point *)b;
            if (p->x < q->x) return -1;
            if (p->x > q->x) return 1;
            if (p->y < q->y) return -1;
            if (p->y > q->y) return 1;
            return 0;
        }
        qsort(pts, m, sizeof(Point), cmp_point);

        /* Remove duplicates */
        int uniq = 0;
        for (int i = 0; i < m; ++i) {
            if (uniq == 0 || pts[i].x != pts[uniq - 1].x || pts[i].y != pts[uniq - 1].y) {
                pts[uniq++] = pts[i];
            }
        }
        if (uniq < 3) {
            free(pts);
            continue;
        }

        /* Convex hull: monotonic chain */
        Point *hull = (Point *)malloc((size_t)(2 * uniq) * sizeof(Point));
        int hs = 0;

        long long cross(Point a, Point b, Point c) {
            long long x1 = b.x - a.x, y1 = b.y - a.y;
            long long x2 = c.x - a.x, y2 = c.y - a.y;
            return x1 * y2 - y1 * x2;
        }

        for (int i = 0; i < uniq; ++i) {
            while (hs >= 2 && cross(hull[hs - 2], hull[hs - 1], pts[i]) <= 0) hs--;
            hull[hs++] = pts[i];
        }
        int lower = hs;
        for (int i = uniq - 2; i >= 0; --i) {
            while (hs > lower && cross(hull[hs - 2], hull[hs - 1], pts[i]) <= 0) hs--;
            hull[hs++] = pts[i];
        }
        if (hs > 1) hs--; /* last point == first point */

        if (hs >= 3) {
            /* Rotating calipers for maximum triangle area on convex polygon */
            long long area2(Point a, Point b, Point c) {
                long long v = cross(a, b, c);
                return v >= 0 ? v : -v;
            }

            for (int i = 0; i < hs; ++i) {
                int k = (i + 2) % hs;
                for (int j = i + 1; j < hs; ++j) {
                    if (j == i) continue;
                    while (1) {
                        int nk = (k + 1) % hs;
                        if (nk == i) break;
                        long long cur = area2(hull[i], hull[j], hull[k]);
                        long long nxt = area2(hull[i], hull[j], hull[nk]);
                        if (nxt > cur) k = nk;
                        else break;
                    }
                    long long a2 = area2(hull[i], hull[j], hull[k]);
                    double area = a2 / 2.0;
                    if (area > best) best = area;
                }
            }
        }

        free(hull);
        free(pts);
    }

    free(stars);

    /* Print without trailing .0 when integer */
    if (fabs(best - floor(best)) < 1e-9) {
        printf("%.0f\n", best);
    } else {
        printf("%.1f\n", best);
    }

    return 0;
}

