typedef long long ll;
typedef pair<ll,ll> pll;

ll cross(pll O, pll A, pll B) {
    return (A.first - O.first) * (B.second - O.second) - (A.second - O.second) * (B.first - O.first);
}

vector<pll> convexHull(vector<pll> points) {
    int n = points.size();
    if (n < 2) return points;
    sort(points.begin(), points.end());
    vector<pll> hull;
    // lower
    for (auto& p : points) {
        while (hull.size() >= 2 && cross(hull[hull.size()-2], hull[hull.size()-1], p) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    // upper
    int lower_size = hull.size();
    for (int i = n-2; i >= 0; i--) {
        while (hull.size() > lower_size && cross(hull[hull.size()-2], hull[hull.size()-1], points[i]) <= 0)
            hull.pop_back();
        hull.push_back(points[i]);
    }
    hull.pop_back();
    return hull;
}

ll polygonArea2(vector<pll>& hull) {
    ll area = 0;
    int n = hull.size();
    for (int i = 0; i < n; i++) {
        area += hull[i].first * hull[(i+1)%n].second;
        area -= hull[(i+1)%n].first * hull[i].second;
    }
    return abs(area);
}

