struct Point {
    long long x, y, b;
};

static long long cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static vector<Point> convexHull(vector<Point> pts) {
    int n = (int)pts.size();
    if (n <= 1) return pts;

    sort(pts.begin(), pts.end(), [](const Point& p1, const Point& p2) {
        if (p1.x != p2.x) return p1.x < p2.x;
        return p1.y < p2.y;
    });

    vector<Point> lower, upper;
    for (const auto& p : pts) {
        while (lower.size() >= 2 &&
               cross(lower[lower.size()-2], lower[lower.size()-1], p) <= 0)
            lower.pop_back();
        lower.push_back(p);
    }
    for (int i = n - 1; i >= 0; --i) {
        const auto& p = pts[i];
        while (upper.size() >= 2 &&
               cross(upper[upper.size()-2], upper[upper.size()-1], p) <= 0)
            upper.pop_back();
        upper.push_back(p);
    }

    lower.pop_back();
    upper.pop_back();
    lower.insert(lower.end(), upper.begin(), upper.end());
    if (lower.empty() && !pts.empty()) lower.push_back(pts[0]);
    return lower;
}

static long long polygonArea2(const vector<Point>& poly) {
    int m = (int)poly.size();
    if (m < 3) return 0;
    long long s = 0;
    for (int i = 0; i < m; ++i) {
        int j = (i + 1) % m;
        s += poly[i].x * poly[j].y - poly[i].y * poly[j].x;
    }
    return llabs(s);
}

