/*
We need the maximum area of a subset of stars such that
max(brightness) - min(brightness) <= d.

For any valid subset, all chosen stars lie inside some brightness interval [L, L+d].
So for each window of stars sorted by brightness, we need the maximum area of a set of points.
That is exactly the area of the convex hull of points in that window.

Thus:
- Sort stars by brightness.
- Use two pointers over brightness.
- For each left index, extend right while brightness diff <= d.
- Compute convex hull area of points in current window, take maximum.

Given the problem statement here, constraints are not shown.
This solution recomputes hull for each window, which is simple and correct.

Area of polygon by shoelace; output as integer if whole, else x.5
(using doubled area as long).
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Star {
        long x, y, b;
        Star(long x, long y, long b) {
            this.x = x;
            this.y = y;
            this.b = b;
        }
    }

    static class Point implements Comparable<Point> {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public int compareTo(Point o) {
            if (x != o.x) return Long.compare(x, o.x);
            return Long.compare(y, o.y);
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static List<Point> convexHull(List<Point> pts) {
        int n = pts.size();
        if (n <= 1) return new ArrayList<>(pts);

        Collections.sort(pts);

        List<Point> lower = new ArrayList<>();
        for (Point p : pts) {
            while (lower.size() >= 2 &&
                    cross(lower.get(lower.size() - 2), lower.get(lower.size() - 1), p) <= 0) {
                lower.remove(lower.size() - 1);
            }
            lower.add(p);
        }

        List<Point> upper = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            Point p = pts.get(i);
            while (upper.size() >= 2 &&
                    cross(upper.get(upper.size() - 2), upper.get(upper.size() - 1), p) <= 0) {
                upper.remove(upper.size() - 1);
            }
            upper.add(p);
        }

        lower.remove(lower.size() - 1);
        upper.remove(upper.size() - 1);
        lower.addAll(upper);

        if (lower.isEmpty() && !pts.isEmpty()) lower.add(pts.get(0));
        return lower;
    }

    static long doubledArea(List<Point> poly) {
        int n = poly.size();
        if (n < 3) return 0;
        long s = 0;
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            s += a.x * b.y - a.y * b.x;
        }
        return Math.abs(s);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        long d = fs.nextLong();

        Star[] stars = new Star[N];
        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            long b = fs.nextLong();
            stars[i] = new Star(x, y, b);
        }

        Arrays.sort(stars, Comparator.comparingLong(s -> s.b));

        long best2 = 0;
        int r = 0;

        for (int l = 0; l < N; l++) {
            while (r < N && stars[r].b - stars[l].b <= d) r++;

            List<Point> pts = new ArrayList<>();
            for (int i = l; i < r; i++) {
                pts.add(new Point(stars[i].x, stars[i].y));
            }

            long area2 = doubledArea(convexHull(pts));
            if (area2 > best2) best2 = area2;
        }

        StringBuilder out = new StringBuilder();
        if ((best2 & 1L) == 0) out.append(best2 / 2);
        else out.append(best2 / 2).append(".5");

        System.out.print(out.toString());
    }
}

