        l = 0
        for r in range(N):
            while stars[r][0] - stars[l][0] > d:
                l += 1
            # Window is [l, r]
            points = [(s[1], s[2]) for s in stars[l:r+1]]
            area = convex_hull_area(points)
            if area > max_area:
                max_area = area

        # Output as integer if whole, else as float
        if max_area == int(max_area):
            print(int(max_area))
        else:
            print(max_area)

solve()

import sys

def convex_hull(points):
    # Monotonic chain. Returns hull in CCW order without repeating first point.
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def polygon_area2(poly):
    # Returns twice the polygon area
    m = len(poly)
    if m < 3:
        return 0
    s = 0
    for i in range(m):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % m]
        s += x1 * y2 - y1 * x2
    return abs(s)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    d = int(next(it))

    stars = []
    for _ in range(N):
        x = int(next(it))
        y = int(next(it))
        b = int(next(it))
        stars.append((b, x, y))

    stars.sort()  # sort by brightness

    ans2 = 0
    r = 0

    for l in range(N):
        while r < N and stars[r][0] - stars[l][0] <= d:
            r += 1

        pts = [(stars[i][1], stars[i][2]) for i in range(l, r)]
        hull = convex_hull(pts)
        ans2 = max(ans2, polygon_area2(hull))

    if ans2 % 2 == 0:
        print(ans2 // 2)
    else:
        print(f"{ans2 // 2}.5")

if __name__ == "__main__":
    main()
